/**
 * WorkerProtocol is one long-lived gRPC bidirectional stream. A worker sends
 * RegisterWorker first; the server answers with RegisterAck as the guaranteed
 * first frame on the response stream before any other server-to-worker
 * message. The worker then sends ActivityResult and Heartbeat messages while
 * the server pushes ActivityTask, ResultAck, DrainRequest, LivenessPing, and
 * CancelActivity messages down the same stream; there is no polling RPC.
 */
export type WorkerProtocolService = typeof WorkerProtocolService;
export const WorkerProtocolService = {
  streamWorker: {
    path: "/aion.WorkerProtocol/StreamWorker" as const,
    requestStream: true as const,
    responseStream: true as const,
    requestSerialize: (value: WorkerToServer): Buffer => Buffer.from(WorkerToServer.encode(value).finish()),
    requestDeserialize: (value: Buffer): WorkerToServer => WorkerToServer.decode(value),
    responseSerialize: (value: ServerToWorker): Buffer => Buffer.from(ServerToWorker.encode(value).finish()),
    responseDeserialize: (value: Buffer): ServerToWorker => ServerToWorker.decode(value),
  },
} as const;

export interface WorkerProtocolServer extends UntypedServiceImplementation {
  streamWorker: handleBidiStreamingCall<WorkerToServer, ServerToWorker>;
}

export interface WorkerProtocolClient extends Client {
  streamWorker(): ClientDuplexStream<WorkerToServer, ServerToWorker>;
  streamWorker(options: Partial<CallOptions>): ClientDuplexStream<WorkerToServer, ServerToWorker>;
  streamWorker(metadata: Metadata, options?: Partial<CallOptions>): ClientDuplexStream<WorkerToServer, ServerToWorker>;
}

export const WorkerProtocolClient = makeGenericClientConstructor(
  WorkerProtocolService,
  "aion.WorkerProtocol",
) as unknown as {
  new (address: string, credentials: ChannelCredentials, options?: Partial<ClientOptions>): WorkerProtocolClient;
  service: typeof WorkerProtocolService;
  serviceName: string;
};

